## 7. Composables (a parte mais importante da lógica de sessão)

### 7.1 `composables/useUser.ts` — estado do usuário

```ts
import { computed, ref } from 'vue'
import { useAuthStore } from '~/stores/auth'
import { useRouter } from '#app'
import type { User } from '~/types/auth'

// Cache para não decodificar o JWT a cada render
let _expireAt = 0

export function useUser() {
  const store = useAuthStore()

  const user = computed(() => store.user)
  const isAuthenticated = computed<boolean>(() => !!store.user)

  const hasValidToken = computed<boolean>(() => {
    if (!_expireAt) return !!store.accessToken
    if (Date.now() >= _expireAt) { _expireAt = 0; return false }

    // Defesa em profundidade: reconferência do claim exp do token armazenado
    const [, expRaw] = (store.accessToken as string)?.split('.') ?? ['', '']
    try {
      const secs = Math.floor(JSON.parse(atob(expRaw.replace(/-/g, '+').replace(/_/g, '/'))).exp)
      const now = Date.now()
      if (now < secs * 1000) { _expireAt = secs * 1000; return true }
      _expireAt = 0
    } catch {
      _expireAt = 0
    }
    return false
  })

  const logout = async () => {
    store.logout()
    localStorage.removeItem('auth-user-id') // fallback se algum token não estiver em cookie
    useRouter().replace('/login')
  }

  const refreshExpiry = (ms: number) => { _expireAt = ms }

  return { user, isAuthenticated, hasValidToken, logout, refreshExpiry }
}
```

### 7.2 `composables/useAuthenticatedFetch.ts` — fetch inteligente com retry de token

É o coração das chamadas a APIs protegidas: se receber 401/403, **tenta renovar o token uma vez** e só então mostra o erro.

```ts
import { ref } from 'vue'
import { useAuthStore } from '~/stores/auth'
import { $fetch } from '#imports'
import type { TokenResponse } from '~/types/auth'
import { useUser } from './useUser'

const MAX_RETRIES = 1 // 1 tentativa extra de renovação

function updateTokens(res: TokenResponse) {
  const s = useAuthStore()
  s.setTokens(res)
  // Atualiza o timestamp de expiração usado por hasValidToken
  const [, expRaw] = s.accessToken!.split('.')
  const secs = Math.floor(JSON.parse(atob(expRaw!.replace(/-/g, '+').replace(/_/g, '/'))).exp)
  useUser().refreshExpiry(secs * 1000)
}

export function useAuthenticatedFetch<T>(
  url: string,
  opts: { headers?: Record<string, string>; key?: number } = {},
): {
  data: ref<T | undefined>
  error: ref<Error | null>
  isLoading: ref<boolean>
  load: () => Promise<void>
} {
  const data = ref<T | undefined>(undefined)
  const error = ref<Error | null>(null)
  const isLoading = ref(true)
  const store = useAuthStore()

  async function load() {
    async function attempt(idx: number) {
      try {
        const headers = { ...opts.headers!, Authorization: `Bearer ${store.accessToken!}` }

        const res = await $fetch<T>(url, {
          method: opts.method ?? 'GET',
          headers,
          body: opts.body,
          key: `${url}-${idx}`, // chaves distintas evitam colisões no Nitro
        })

        data.value = res
        if (res && 'access_token' in res) updateTokens(res as TokenResponse)
        isLoading.value = false
      } catch (e: any) {
        if (e.status === 401 || e.status === 403) {
          if (idx < MAX_RETRIES) {
            try {
              const { data: refresh } = await $fetch<TokenResponse>('/api/auth/refresh', {
                method: 'POST',
                headers: { Authorization: `Bearer ${store.accessToken!}` },
              })
              if (refresh) updateTokens(refresh)
              await attempt(idx + 1) // refetch com os tokens renovados
            } catch {
              fatalLogout()
            }
          } else {
            fatalLogout()
          }
        } else {
          fatalLogout()
        }
        // Não rejeitamos a promessa aqui — a cadeia termina naturalmente
      }
    }

    await attempt(0)
    isLoading.value = false
  }

  function fatalLogout() {
    useAuthStore().logout()
    useUser().logout() // dispara redirect para /login
  }

  return { data, error, isLoading, load }
}
```

### 7.3 `composables/useRefreshToken.ts` — fluxo manual de refresh (para casos específicos)

```ts
import { useAuthStore } from '~/stores/auth'
import { useUser } from './useUser'
import { useRouter } from '#app'

export function useRefreshToken() {
  return async (): Promise<boolean> => {
    const store = useAuthStore()

    try {
      const { data } = await $fetch('/api/auth/refresh', {
        method: 'POST',
        headers: { Authorization: `Bearer ${store.accessToken!}` },
      })

      if (data) {
        store.setTokens(data as any)
        useUser().refreshExpiry(Number((data as any).access_token.split('.')[1]?.replace(/-/g, '+').replace(/_/g, '/') ? JSON.parse(atob((data as any).access_token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')).exp : 0) * 1000))
        return true
      }
    } catch (e: any) {
      if (e.status === 401 && e.data?.refresh_token) {
        // O token de refresh também morreu → logout definitivo
        await $fetch('/api/auth/logout', {
          method: 'POST',
          body: { refresh_token: String(e.data.refresh_token) },
        })
      }
      useAuthStore().logout()
      useRouter().replace('/login')
      return false
    }
  }
}
```

