## 8. Middleware de proteção global — `middleware/auth.global.ts`

Roda **antes de qualquer rota**. Permite apenas: assets do Nuxt, caminhos públicos e rotas de auth (login/refresh/logout não precisam de token).

```ts
import { defineEventHandler } from 'h3'
import { getCookie } from 'h3'
import { jwtVerify } from 'jose'
import { runtimeConfig } from '#imports'

const STATIC_PATTERNS = ['/_(static|fonts|images)', '/@media*', /^\/\d+\/']
const PUBLIC_ROUTES = ['/login', '/register']

function isPublicPath(path: string): boolean {
  if (STATIC_PATTERNS.some(p => p.test(path))) return true
  if (PUBLIC_ROUTES.some(r => path === r || path.startsWith(r + '/'))) return true
  return path === '/' || path.startsWith('/_nuxt')
}

// JWT Secret vem do runtimeConfig.server (definido em .env)
const JWT_SECRET = runtimeConfig.server.jwtSecret

export default defineEventHandler((event) => {
  if (isPublicPath(event.path)) return true

  // Aceita token em Authorization ou no cookie (fallback para navegadores antigos)
  const bearer = (event.node.req.headers.authorization as string | undefined)?.startsWith('Bearer ')
    ? (event.node.req.headers.authorization!.slice(7))
    : getCookie(event, 'access_token')

  if (!bearer) return { path: '/login' }

  try {
    const { getExpirationTime } = jwtVerify(bearer, new TextEncoder().encode.JWT_SECRET as Uint8Array, {
      algorithms: ['HS256'],
      clockTimestamp: Math.floor(Date.now() / 1000),
    })
    const exp = getExpirationTime()?.valueOf() ?? Infinity
    if (Date.now() >= exp * 1000) return { path: '/login' } // expirado
  } catch {
    // Assinatura inválida / alg incorreto
    return { path: '/login' }
  }

  return true
})
```

> Em produção, substitua a verificação casada por uma **tabela/sessão de revogação** (Redis ou banco) criada pelo NestJS no `refresh`/`logout`. Assim o middleware pode devolver `{ path: '/login' }` sem decodificar JWT a cada requisição.

