const showPassword = ref(false)
const submitting = ref(false)
const error = ref('')

const store = useAuthStore()
const router = useRouter()
const { logout } = useUser()

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const MIN_PASS = 6

function validate(): boolean {
  const v = emailInput.value.trim()
  if (!v) { error.value = 'O e-mail é obrigatório.'; return false }
  if (!EMAIL_RE.test(v)) { error.value = 'Informe um e-mail válido.'; return false }
  if (passwordInput.value.length < MIN_PASS) {
    error.value = 'A senha precisa ter no mínimo 6 caracteres.'
    return false
  }
  error.value = ''
  return true
}

async function onSubmit() {
  if (!validate()) return
  error.value = ''
  submitting.value = true

  try {
    await store.login({ email: emailInput.value.trim(), password: passwordInput.value })
    // Mostra loading na UI antes de navegar
    setTimeout(() => router.replace('/dashboard'), 1200)
  } catch (e: any) {
    const detail = e.data?.detail
    error.value = detail ?? (e.status === 401 ? 'E-mail ou senha incorretos.' : 'Ops, deu erro. Tente novamente.')
  } finally {
    submitting.value = false
  }
}
</script>

