<script setup lang="ts">
import { watch } from 'vue'
import { useRouter } from '#app'
import { useUser } from '~/composables/useUser'

const route = useRouter()
const { isAuthenticated, logout } = useUser()
const firstLoad = true
let loggedOutOnce = false

// 1º carregamento (inclui reloads): redireciona para login só uma vez
watch([isAuthenticated], (newVal, oldVal) => {
  if (firstLoad && !newVal && !oldVal) {
    firstLoad = false
    route.replace('/login')
  }
  // Após logout real: limpa tudo e leva para login (uma vez por sessão)
  if (!newVal && !firstLoad && !loggedOutOnce) {
    loggedOutOnce = true
    logout()
  }
}, { immediate: true })
