## 4. Endpoint mínimo necessário no NestJS

Adicione estes endpoints ao módulo `auth` do backend (a lógica de hash/revogação segue o padrão que você já tem):

```ts
@Controller('auth')
export class AuthService {
  constructor(private jwtService: JwtService, private sessionService: SessionService) {}

  @Post('login')
  async login(@Body() creds: LoginPayload, @Resp() res: Res): Promise<ApiResponse<TokenResponse>> {
    const user = await this.userService.findByEmail(creds.email)
    const ok = await bcrypt.compare(creds.password, user.passwordHash)
    if (!ok) throw Object.assign(new BadRequestException('E-mail ou senha incorretos'), { statusCode: 401 })

    const token = await this.jwtService.sign({ sub: user.id, username: user.username })
    const refresh = await this.utils.generateRefreshToken(user.id)

    // ⬇️ Camada essencial de segurança: cookie httpOnly
    res.cookie('access_token', token, { httpOnly: true, secure: true, sameSite: 'lax', maxAge: 15 * 60 * 1000 })
    res.cookie('refresh_token', refresh, { httpOnly: true, secure: true, sameSite: 'lax', maxAge: 7 * 24 * 60 * 60 * 1000 })

    return { success: true, data: { access_token: token, refresh_token: refresh, user } }
  }

  @Post('refresh')
  async refresh(@Body() body: { refresh_token: string }, @Resp() res: Res): Promise<ApiResponse<TokenResponse>> {
    const tokens = await this.utils.validateAndRotate(body.refresh_token) // aceita revogação de tokens roubados
    res.cookie('access_token', tokens.access_token, { httpOnly: true, secure: true, sameSite: 'lax', maxAge: 15 * 60 * 1000 })
    return { success: true, data: tokens.response }
  }

  @Post('logout')
  async logout(@Body() body: { refresh_token: string }, @Resp() res: Res): Promise<void> {
    await this.sessionService.revoke(body.refresh_token)
    res.clearCookie('access_token', { path: '/', httpOnly: true, sameSite: 'lax' })
    res.clearCookie('refresh_token', { path: '/', httpOnly: true, sameSite: 'lax' })
  }

  @UseGuards(JwtAuthGuard)
  @Get('me')
  async me(@Req() req: Request): Promise<ApiResponse<User>> {
    return { success: true, data: await this.userService.findById(req.user!.id) }
  }
}
```

> Adicione `app.use(require('cookie-parser')())` no módulo Express do NestJS para que os `res.cookie()` funcionem.

