## 6. Store de autenticação (Pinia) — `stores/auth.store.ts`

```ts
import { defineStore } from 'pinia'
import { $fetch } from '#imports'
import type { TokenResponse, User } from '~/types/auth'

export const useAuthStore = defineStore('auth', {
  state: () => ({
    user: null as User | null,
    accessToken: null as string | null,
    refreshToken: null as string | null,
  }),

  getters: {
    isAuthenticated: (state) => !!state.user,
  },

  actions: {
    async login(credentials: { email: string; password: string }): Promise<void> {
      const { data: res } = await $fetch<TokenResponse>('/api/auth/login', {
        method: 'POST',
        body: credentials,
      })
      if (!res?.success) throw new Error(res?.detail ?? 'Falha ao login')
      this.accessToken = res.data.access_token
      this.refreshToken = res.data.refresh_token
      this.user = res.data.user
    },

    logout(): void {
      this.accessToken = null
      this.refreshToken = null
      this.user = null
    },

    setTokens(tokens: TokenResponse): void {
      this.accessToken = tokens.access_token
      this.refreshToken = tokens.refresh_token
      this.user = tokens.user
    },
  },
})
```

> **Persistência entre abas/navegação**: adicione `{ persist: { key: 'auth-store' } }` no segundo parâmetro de `defineStore`, usando `@pinia/persist`.

